import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as B,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"USB 协议分层","description":"","frontmatter":{"title":"USB 协议分层","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/usb-protocol.md","filePath":"cs/usb-protocol.md","lastUpdated":1789023840000}'),d={name:"cs/usb-protocol.md"};function c(S,a,A,h,P,u){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="usb-协议分层" tabindex="-1">USB 协议分层 <a class="header-anchor" href="#usb-协议分层" aria-label="Permalink to &quot;USB 协议分层&quot;">​</a></h1><div class="epigraph"><p>USB 把设备、配置、接口、端点叠成树，传输分控制/批量/中断/等时；主机控制器用描述符 DMA 调度微帧，而不是 CPU 比特翻转 D+/D−。</p><footer>—— 据 USB Implementers Forum, USB Specification；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/dma-scatter-gather">上一课</a>给出通用 DMA。<a href="/cs/pcie-lanes">PCIe</a> 上的 xHCI 是主机控制器端点。缺口是 <strong>USB 分层</strong>：与 PCIe TLP 不同的包与端点模型，让键盘、盘、网共用一条树形总线。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>USB：主机为根的树，集线器分层。设备描述符→配置→接口→端点。传输类型：控制（枚举）、批量（盘）、中断（HID 轮询间隔）、等时（音频，允许丢）。缺口不是再讲 SG 表，而是 xHCI Transfer Ring 上的 TRB 如何对应这些传输。物理层随代变（LS/FS/HS/SS），本课不画眼图。</p><p>枚举：复位、取描述符、设地址、配配置——固件/OS 早期就会做，与后课 BIOS 枚举 PCI 并列。</p><h3 id="usb-不是「小版-pcie」" tabindex="-1">USB 不是「小版 PCIe」 <a class="header-anchor" href="#usb-不是「小版-pcie」" aria-label="Permalink to &quot;USB 不是「小版 PCIe」&quot;">​</a></h3><p>USB 是主机轮询/调度的共享树（尽管 SS 有更多点对点味道），设备不主动发任意 Memory TLP 到全系统（USB4/雷电另议）。把优盘当 PCIe NVMe 端点，BAR 模型会套错。对主机而言优盘是 SCSI/UAS 命令再进批量端点。</p><p><span class="marginnote">USB 规范是分层权威。Patterson/Hennessy 把 USB 当 I/O 例子。xHCI 规范描述环与 DMA。本课钉层次与传输类，不背描述符每个字段。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>软件：URB/请求块 → 主机控制器驱动填 TRB → DMA → 端口收发包。盘：Bulk + BOT 或 UAS。HID：中断入端点。与 <a href="/cs/msi-msix">MSI</a>：xHCI 用 MSI-X 通知环事件。电源：挂起与远程唤醒点名。</p>',11)),(e(),l(E,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TREE%5B%22%E4%B8%BB%E6%9C%BA-%E9%9B%86%E7%BA%BF%E5%99%A8-%E8%AE%BE%E5%A4%87%E6%A0%91%22%5D%20--%3E%20EP%5B%22%E7%AB%AF%E7%82%B9%22%5D%0A%20%20EP%20--%3E%20XFER%5B%22%E6%8E%A7%E5%88%B6%2F%E6%89%B9%E9%87%8F%2F%E4%B8%AD%E6%96%AD%2F%E7%AD%89%E6%97%B6%22%5D%0A%20%20XFER%20--%3E%20xHCI%5B%22xHCI%20DMA%20%E7%8E%AF%22%5D%0A%20%20xHCI%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%9B%B4%E7%AE%80%E5%8D%95%E7%9A%84%E7%89%87%E4%B8%8A%E4%B8%B2%E5%8F%A3%E6%80%BB%E7%BA%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>对比 I²C/SPI：那些是片内短线，无 USB 描述符树。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课片上低速总线给传感器与闪存颗粒旁路。显示链路（eDP）不是 USB，帧缓冲课再接。本课把「外设树」从 PCIe 交换机树区分开：PCIe 枚举配置空间；USB 枚举描述符。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 USB4 隧道 PCIe 的全部，不把 Type-C PD 电源合同当主体。不讨论驱动签名。不进入音频等时抖动的信号处理。</p><p>后课默认：USB 是主机调度的端点传输；xHCI 用 DMA 环；与 PCIe 端点模型不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>设备树 + 四类传输；控制通路做枚举。</li><li>xHCI 把传输变成 DMA 描述符。</li><li>不是 PCIe Memory TLP 的缩微。</li><li>出处：USB Specification；xHCI；Patterson and Hennessy, COD。</li></ul>',8))])}const m=s(d,[["render",c]]);export{I as __pageData,m as default};
